mapper.update:
UPDATE wms_batch_location_balance
SET quantity = quantity - #{line.quantity}, reserved_quantity = reserved_quantity - #{line.quantity},
    picked_quantity = picked_quantity - #{line.quantity}
WHERE tenant_id = #{tenantId} AND batch_no = #{line.batchNo} AND location_id = #{line.locationId}
  AND seller_sku = #{line.sellerSku} AND quantity >= #{line.quantity}
  AND reserved_quantity >= #{line.quantity} AND picked_quantity >= #{line.quantity}

UPDATE wms_sales_shipment SET oms_sync_status = 'SYNCED', sync_error = NULL,
    sync_attempts = sync_attempts + 1, synced_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND package_id = #{packageId}

mapper.select:
SELECT pp.package_id, a.outbound_id, w.sales_order_id, p.warehouse_id, pp.pick_id, a.sales_line_id,
       a.seller_sku, a.location_id, COALESCE(p.location_code, p.barcode) AS location_code,
       a.batch_no, o.order_id, o.reference_id, pp.quantity, s.shipped_at, s.operator_id

JOIN wms_sales_shipment s ON s.tenant_id = pp.tenant_id AND s.package_id = pp.package_id
JOIN wms_sales_pick_work w ON w.tenant_id = a.tenant_id AND w.outbound_id = a.outbound_id
WHERE pp.tenant_id = #{tenantId}
AND o.reference_id = #{filter.purchaseOrderId}
AND a.batch_no = #{filter.batchNo}
AND w.sales_order_id = #{filter.salesOrderId}
AND a.outbound_id = #{filter.outboundId}
AND pp.package_id = #{filter.packageId}
AND p.warehouse_id = #{filter.warehouseId}
AND a.location_id = #{filter.locationId}
AND a.seller_sku = #{filter.sellerSku}
ORDER BY s.shipped_at DESC, pp.package_id, pp.pick_id
